async function execute(f, executable = program) {
  const calls = [], failures = [], evidence = [], effects = [], counts = new Map();
  const answer = async (endpoint, params, expected, value) => {
    assert.deepEqual(clone(params), expected, `Exact immutable parameters for ${endpoint}`);
    const count = (counts.get(endpoint) ?? 0) + 1;
    counts.set(endpoint, count); calls.push({ endpoint, params: clone(params) });
    if (f.reject === `${endpoint}:${count}`) throw new Error("TEST API transport failure");
    return { data: clone(typeof value === "function" ? value(count) : value) };
  };
  const forbidden = name => { effects.push(name); throw new Error(`Forbidden capability: ${name}`); };
  const closed = (name, methods) => new Proxy(methods, { get: (target, key) => Object.hasOwn(target, key) ? target[key] : forbidden(`${name}.${String(key)}`) });
  const github = closed("github", { rest: closed("rest", {
    pulls: closed("pulls", { get: params => answer("pulls.get", params, { ...apiRepo, pull_number: 350 }, n => f.pulls[n - 1]) }),
    repos: closed("repos", {
      get: params => answer("repos.get", params, apiRepo, n => f.repositories[n - 1]),
      getBranch: params => answer("repos.getBranch", params, { ...apiRepo, branch: "main" }, n => f.branches[n - 1]),
      compareCommitsWithBasehead: params => {
        assert.ok(Object.hasOwn(f.comparisons, params.basehead), "Only exact base/head and frozen-anchor ancestry reads");
        return answer("repos.compare", params, { ...apiRepo, basehead: params.basehead }, f.comparisons[params.basehead]);
      }
    }),
    git: closed("git", {
      getCommit: params => {
        assert.ok([anchor, f.base, f.head].includes(params.commit_sha));
        return answer("git.getCommit", params, { ...apiRepo, commit_sha: params.commit_sha }, f.commits[params.commit_sha]);
      },
      getTree: params => answer("git.getTree", params, { ...apiRepo, tree_sha: params.tree_sha, recursive: "true" }, f.trees[params.tree_sha]),
      getBlob: params => {
        assert.ok(expectedTuple.some(item => [item.old_blob, item.new_blob].includes(params.file_sha)), "Only frozen finite blobs may be read");
        return answer("git.getBlob", params, { ...apiRepo, file_sha: params.file_sha }, f.blobs[params.file_sha]);
      }
    })
  }) });
  const sandbox = createContext({ github, context: clone(f.context), Buffer,
    core: closed("core", { setFailed: message => failures.push(message), info: message => evidence.push(message) }),
    require: name => name === "node:crypto" ? { createHash } : forbidden(`require:${name}`) });
  await executable.runInContext(sandbox, { timeout: 2000 });
  assert.deepEqual(effects, [], "No mutable listFiles, checkout, head execution, writable API, or other capability");
  return { calls, failures, evidence };
}
async function accepted(f, direction) {
  const result = await execute(f);
  assert.deepEqual(result.failures, [], result.failures.join("\n"));
  assert.equal(result.evidence.length, 1);
  assert.deepEqual(JSON.parse(result.evidence[0]), { guard: "trusted-platform-stable31-pending-transition", repository: repo.full_name,
    direction, pr: 350, base: f.base, head: f.head, anchor, tuple_identity: expectedIdentity, tuple: direction === "noop" ? [] : expectedTuple });
  assert.deepEqual(result.calls.slice(-3).map(call => call.endpoint), ["pulls.get", "repos.get", "repos.getBranch"]);
  return result;
}
async function refused(f, reason, executable) {
  const result = await execute(f, executable);
  assert.equal(result.failures.length, 1, "Refusal fails the check exactly once");
  if (reason) assert.match(result.failures[0], reason);
  assert.deepEqual(result.evidence, [], "Refusal emits no positive authorization evidence");
  return result;
}

